css:
.fairview-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2433;
    background: linear-gradient(160deg, #eef1f6 0%, #e4e8f0 100%);
    border-radius: 18px;
}

.fairview-container * {
    box-sizing: border-box;
}

.fairview-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203b 0%, #1c3358 55%, #29466f 100%);
    color: #f3f6fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 59, 0.32);
    border-bottom: 3px solid #c9a14a;
}

.fairview-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f6e6bf;
}

.fairview-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #d8c189;
    background: rgba(201, 161, 74, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.fairview-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6deea;
}

.fairview-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #243a5e;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.fairview-period-counter #currentDay,
.fairview-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203b;
}

.fairview-round-name {
    background: #d7dfee;
    color: #11203b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.fairview-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: #f6ecd6;
    padding: 4px 12px;
    border-radius: 999px;
}

.fairview-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.fairview-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6dde9;
    box-shadow: 0 4px 14px rgba(17, 32, 59, 0.06);
    border-top: 4px solid #29466f;
}

.fairview-card-ifrs { border-top-color: #1f5fa8; }
.fairview-card-quality { border-top-color: #1d7a5f; }
.fairview-card-transparency { border-top-color: #c9a14a; }
.fairview-card-risk { border-top-color: #b1402f; }

.fairview-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e6c81;
}

.fairview-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203b;
}

.fairview-card-ifrs .fairview-value { color: #1f5fa8; }
.fairview-card-quality .fairview-value { color: #1d7a5f; }
.fairview-card-transparency .fairview-value { color: #a9842f; }
.fairview-card-risk .fairview-value { color: #b1402f; }

.fairview-sublabel {
    font-size: 0.75rem;
    color: #6b788c;
    line-height: 1.35;
}

/* Audit risk: low rating is GOOD (green), high is BAD (red). */
.fairview-risk-low .fairview-value { color: #1d7a5f; }
.fairview-risk-low { border-top-color: #1d7a5f; }
.fairview-risk-high .fairview-value { color: #b1402f; }
.fairview-risk-high { border-top-color: #b1402f; }

.fairview-ledger-bar {
    display: flex;
    justify-content: space-between;
    align-items: stretch;
    gap: 14px;
    margin-bottom: 18px;
}

.fairview-ledger-item {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 4px;
    background: #11203b;
    color: #eaf0f8;
    padding: 12px 18px;
    border-radius: 12px;
    border-left: 4px solid #c9a14a;
}

.fairview-ledger-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 700;
    color: #b9c6da;
}

.fairview-ledger-item #ebitDisplay,
.fairview-ledger-item #covenantDisplay {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 0.3px;
    color: #f6e6bf;
}

.fairview-covenant-breach #covenantDisplay {
    color: #ff9a86;
}

.fairview-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #29466f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 59, 0.05);
}

.fairview-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.fairview-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203b;
    margin-bottom: 6px;
}

.fairview-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2b3850;
}

.fairview-briefing-text strong { color: #1d7a5f; }
.fairview-briefing-text em { color: #8a5a12; font-style: italic; }

.fairview-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6dde9;
    box-shadow: 0 4px 14px rgba(17, 32, 59, 0.06);
}

.fairview-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203b;
    border-bottom: 2px solid #e4e8f0;
    padding-bottom: 8px;
}

.fairview-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #1f2d44;
    margin: 14px 0 6px;
}

.fairview-container select,
.fairview-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcc8da;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fc;
    color: #1c2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.fairview-container select:focus,
.fairview-container input[type="number"]:focus {
    outline: none;
    border-color: #1f5fa8;
    box-shadow: 0 0 0 3px rgba(31, 95, 168, 0.15);
}

.fairview-container select option {
    background-color: #ffffff;
    color: #1c2433;
}

.fairview-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f5fa8;
}

.fairview-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #243a5e;
    margin-top: 4px;
}

.fairview-range-readout span:last-child {
    color: #1d7a5f;
    font-weight: 800;
}

.fairview-hint {
    font-size: 0.8rem;
    color: #6b788c;
    margin-top: 4px;
    line-height: 1.4;
}

.fairview-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.fairview-container .btn-primary {
    background: linear-gradient(135deg, #1c3358 0%, #29466f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #f6e6bf;
    box-shadow: 0 6px 16px rgba(28, 51, 88, 0.28);
}

.fairview-container .btn-primary:hover {
    filter: brightness(1.08);
}

.fairview-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcc8da;
    color: #5e6c81;
}

.fairview-coach {
    background: #11203b;
    color: #eaf0f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 59, 0.22);
    border-left: 4px solid #c9a14a;
}

.fairview-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #d8c189;
    margin-bottom: 8px;
}

.fairview-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.fairview-coach-body strong { color: #f6e6bf; }
.fairview-coach-body em { color: #ffc99a; font-style: italic; }

.fairview-history,
.fairview-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6dde9;
    box-shadow: 0 4px 14px rgba(17, 32, 59, 0.06);
}

.fairview-history h3,
.fairview-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203b;
}

.fairview-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #1f2d44;
}

.fairview-container table#usfHistoryTable th {
    background: #eaeef5;
    color: #11203b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d3dbe8;
}

.fairview-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f6;
}

.fairview-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fc;
}

.fairview-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .fairview-container {
        padding: 14px;
    }
    .fairview-header h1 {
        font-size: 1.7rem;
    }
    .fairview-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .fairview-value {
        font-size: 2rem;
    }
    .fairview-clock {
        margin-left: 0;
    }
    .fairview-period-counter {
        font-size: 0.88rem;
    }
    .fairview-ledger-bar {
        flex-direction: column;
        gap: 10px;
    }
    .fairview-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained, navy/green) */
.fairview-cm { background:#f5f7f6; color:#11203b; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(17,32,59,0.2); }
.fairview-cm-head { text-align:center; border-bottom:1px solid #d6ded9; padding-bottom:14px; margin-bottom:16px; }
.fairview-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#1d7a5f; font-weight:700; }
.fairview-cm-scorewrap { margin:8px 0 2px; }
.fairview-cm-score { font-size:52px; font-weight:800; color:#11203b; line-height:1; }
.fairview-cm-score-max { font-size:20px; color:#7f8a86; font-weight:600; }
.fairview-cm-grade { font-size:19px; font-weight:700; color:#11203b; margin-top:4px; }
.fairview-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.fairview-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.fairview-cm-met { background:#cfe8dc; color:#136b48; }
.fairview-cm-fail { background:#f1dbd5; color:#9c3626; }
.fairview-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.fairview-cm-metric { background:#e7eeeb; border-radius:10px; padding:12px 16px; min-width:96px; text-align:center; }
.fairview-cm-metric-val { font-size:22px; font-weight:800; color:#11203b; }
.fairview-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#4f6a60; margin-top:3px; }
.fairview-cm-insights { background:#e7eeeb; border-radius:10px; padding:14px 18px; }
.fairview-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#1d7a5f; font-weight:700; margin-bottom:8px; }
.fairview-cm-insights ul { margin:0; padding-left:18px; }
.fairview-cm-insights li { font-size:14px; line-height:1.5; color:#233a33; margin-bottom:7px; }

