(function() {
    'use strict';

    class FairViewAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Fair View`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Rheinwerk Systeme AG).
            this.EBIT_FULL = 51.0;       // €M — full Adler recognition
            this.EBIT_CORRECT = 46.8;    // €M — IFRS-15-correct, after deferring ~€4.2M
            this.ADLER_EBIT = 4.2;       // €M of EBIT riding on the Adler choice
            this.NET_DEBT = 150.0;       // €M — implied so 150/51 = 2.94x, 150/46.8 = 3.21x
            this.COVENANT_MAX = 3.0;     // net-debt / EBIT
            this.RECEIVABLE = 9.0;       // €M overdue, 180+ days, client in restructuring
            this.BONUS_POOL = 3.8;       // €M management bonus at risk

            // Starting KPIs — low, with headroom so every later choice still registers.
            this.START_IFRS = 18;
            this.START_QUALITY = 16;
            this.START_TRANSPARENCY = 14;
            this.START_RISK = 62;        // audit risk: HIGH is bad, LOW is good

            // Targets for the end summary.
            this.TARGET_COMPOSITE = 70;
            this.RISK_FLOOR = 22;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ifrs: this.START_IFRS,
                    quality: this.START_QUALITY,
                    transparency: this.START_TRANSPARENCY,
                    risk: this.START_RISK,
                    ebit: this.EBIT_FULL,
                    eclTaken: 0,
                    breachConcealed: false,
                    incentiveLed: false,
                    ifrsHistory: [this.START_IFRS],
                    qualityHistory: [this.START_QUALITY],
                    riskHistory: [this.START_RISK],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Neutral / middling seed — NOT the textbook-correct play. A click-through
                // must not auto-win: defaults book too much revenue, under-provide the
                // receivable, respond to the auditor with mixed reasoning, and defend on optics.
                state.decisions = {
                    recognition: `partial`,
                    obligations: `two`,
                    allocation: 50,
                    provision: `partial`,
                    ecl: 20,
                    disclosure: `contingency`,
                    response: `mixed`,
                    breach: `auditonly`,
                    independence: `document`,
                    defense: `balanced`,
                    pattern: `acknowledge`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rec = document.getElementById(`recognitionInput`);
                const obl = document.getElementById(`obligationsInput`);
                const al = document.getElementById(`allocationInput`);
                if (rec) decisions.recognition = rec.value;
                if (obl) decisions.obligations = obl.value;
                if (al) decisions.allocation = parseInt(al.value, 10);
                if (!Number.isFinite(decisions.allocation) || decisions.allocation < 0 || decisions.allocation > 100) {
                    warn(`warn_allocation_range`); return false;
                }
            } else if (round === 2) {
                const pr = document.getElementById(`provisionInput`);
                const ec = document.getElementById(`eclInput`);
                const di = document.getElementById(`disclosureInput`);
                if (pr) decisions.provision = pr.value;
                if (ec) decisions.ecl = parseFloat(ec.value);
                if (di) decisions.disclosure = di.value;
                if (!Number.isFinite(decisions.ecl) || decisions.ecl < 0 || decisions.ecl > 100) {
                    warn(`warn_ecl_range`); return false;
                }
            } else if (round === 3) {
                const re = document.getElementById(`responseInput`);
                const br = document.getElementById(`breachInput`);
                const ind = document.getElementById(`independenceInput`);
                if (re) decisions.response = re.value;
                if (br) decisions.breach = br.value;
                if (ind) decisions.independence = ind.value;
            } else if (round === 4) {
                const de = document.getElementById(`defenseInput`);
                const pa = document.getElementById(`patternInput`);
                const cv = document.getElementById(`convictionInput`);
                if (de) decisions.defense = de.value;
                if (pa) decisions.pattern = pa.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let ifrsDelta = 0, qualityDelta = 0, transparencyDelta = 0, riskDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // IFRS 15: recognition follows SATISFIED obligations, not contract signing
                // (Common Error 1 — sign-equals-revenue).
                if (d.recognition === `ifrs15correct`) {
                    ifrsDelta += 16; qualityDelta += 15; riskDelta -= 8;
                    ds.ebit = this.EBIT_CORRECT;
                    coachKey = `coach_r1_correct`;
                } else if (d.recognition === `partial`) {
                    ifrsDelta += 3; qualityDelta -= 2; riskDelta -= 1;
                    ds.ebit = this.EBIT_FULL - 1.4; // defers only the service obligation
                    coachKey = `coach_r1_partial`;
                } else { // full
                    ifrsDelta -= 12; qualityDelta -= 14; riskDelta += 12;
                    ds.ebit = this.EBIT_FULL;
                    coachKey = `coach_r1_full`;
                }

                // Performance-obligation analysis: three distinct obligations is the IFRS 15 core.
                if (d.obligations === `three`) {
                    ifrsDelta += 9; qualityDelta += 4; riskDelta -= 4;
                    if (d.recognition === `ifrs15correct`) coachKey = `coach_r1_sharp`;
                } else if (d.obligations === `two`) {
                    ifrsDelta += 2;
                } else { // single
                    ifrsDelta -= 9; qualityDelta -= 5; riskDelta += 5;
                    if (d.recognition !== `full`) coachKey = `coach_r1_single`;
                }

                // Relative SSP allocation rigour.
                if (d.allocation >= 70) { ifrsDelta += 6; qualityDelta += 2; }
                else if (d.allocation >= 40) { ifrsDelta += 2; }
                else { ifrsDelta -= 5; riskDelta += 3; }

                summaryKey = (d.recognition === `ifrs15correct` && d.obligations === `three`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // IFRS 9 ECL: restructuring is objective evidence of impairment
                // (Common Error 3 — optimistic receivable).
                if (d.provision === `full`) {
                    ifrsDelta += 13; qualityDelta += 12; riskDelta -= 7;
                    coachKey = `coach_r2_full`;
                } else if (d.provision === `partial`) {
                    ifrsDelta -= 2; qualityDelta -= 3; riskDelta += 3;
                    coachKey = `coach_r2_partial`;
                } else { // none
                    ifrsDelta -= 12; qualityDelta -= 12; riskDelta += 13;
                    ds.incentiveLed = true;
                    coachKey = `coach_r2_none`;
                }

                ds.eclTaken = Math.round(this.RECEIVABLE * (d.ecl / 100) * 10) / 10;
                // A restructuring client warrants a substantial ECL; a token figure understates it.
                if (d.ecl >= 70) { ifrsDelta += 6; qualityDelta += 4; riskDelta -= 3; }
                else if (d.ecl >= 35) { ifrsDelta += 2; }
                else { ifrsDelta -= 5; qualityDelta -= 4; riskDelta += 4; }

                // Disclosure posture vs the true-and-fair-view obligation.
                if (d.disclosure === `notefull`) {
                    transparencyDelta += 17; riskDelta -= 6;
                    if (d.provision === `full`) coachKey = `coach_r2_transparent`;
                } else if (d.disclosure === `contingency`) {
                    transparencyDelta += 2; riskDelta += 3;
                } else { // silent
                    transparencyDelta -= 12; riskDelta += 10; qualityDelta -= 5;
                    coachKey = `coach_r2_silent`;
                }

                summaryKey = (d.provision === `full` && d.disclosure === `notefull`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Auditor query: respond on the standards, not the pressure.
                if (d.response === `standards`) {
                    ifrsDelta += 10; qualityDelta += 6; riskDelta -= 6;
                    coachKey = `coach_r3_standards`;
                } else if (d.response === `mixed`) {
                    ifrsDelta += 2; riskDelta += 2;
                } else { // pressure
                    ifrsDelta -= 10; qualityDelta -= 9; riskDelta += 10;
                    ds.incentiveLed = true;
                    coachKey = `coach_r3_pressure`;
                }

                // The covenant breach: transparent, proactive disclosure is part of the duty
                // (Common Error 2 — concealed breach).
                if (d.breach === `proactive`) {
                    transparencyDelta += 17; riskDelta -= 7; qualityDelta += 3;
                    coachKey = (d.response === `standards`) ? `coach_r3_proactive` : coachKey;
                } else if (d.breach === `auditonly`) {
                    transparencyDelta -= 2; riskDelta += 5;
                } else { // conceal
                    transparencyDelta -= 15; riskDelta += 15; qualityDelta -= 5;
                    ds.breachConcealed = true;
                    coachKey = `coach_r3_conceal`;
                }

                // Familiarity / independence threat (Common Error 5).
                if (d.independence === `freshreview`) {
                    riskDelta -= 7; qualityDelta += 3; transparencyDelta += 3;
                } else if (d.independence === `document`) {
                    riskDelta -= 2;
                } else { // rely
                    riskDelta += 10; qualityDelta -= 5;
                    coachKey = `coach_r3_rely`;
                }

                summaryKey = (d.response === `standards` && d.breach === `proactive` && d.independence !== `rely`) ? `sum_r3_good` : (d.breach === `conceal` ? `sum_r3_conceal` : `sum_r3_weak`);
            } else if (round === 4) {
                // Audit committee: faithful representation vs flattering the metric.
                if (d.defense === `substance`) {
                    ifrsDelta += 7; qualityDelta += 12; transparencyDelta += 9; riskDelta -= 10;
                    coachKey = `coach_r4_substance`;
                } else if (d.defense === `balanced`) {
                    qualityDelta += 2; transparencyDelta += 2; riskDelta += 2;
                } else { // metric
                    ifrsDelta -= 11; qualityDelta -= 14; transparencyDelta -= 9; riskDelta += 14;
                    ds.incentiveLed = true;
                    coachKey = `coach_r4_metric`;
                }

                // The pattern: the audit-committee chair reads the direction of every estimate.
                if (d.pattern === `demonstrate`) {
                    qualityDelta += 10; riskDelta -= 8; transparencyDelta += 3;
                    coachKey = (d.defense === `substance`) ? `coach_r4_demonstrate` : coachKey;
                } else if (d.pattern === `acknowledge`) {
                    qualityDelta += 1; riskDelta += 2;
                } else { // deny
                    qualityDelta -= 9; riskDelta += 11;
                    coachKey = `coach_r4_deny`;
                }

                // Conviction nudges earnings quality and audit risk.
                const cvAdj = Math.round((d.conviction - 60) / 8);
                qualityDelta += cvAdj;
                riskDelta -= Math.round(cvAdj / 2);
            }

            // If a covenant breach was concealed, every later round keeps bleeding trust
            // until it surfaces — converting a technical breach into a trust crisis.
            if (round >= 3 && ds.breachConcealed && d.breach !== `proactive`) {
                transparencyDelta -= 4; riskDelta += 4;
            }

            // Apply deltas (KPIs bounded 0–100; risk inverted — clamp away from 0/100 a touch).
            ds.ifrs = Math.max(0, Math.min(100, ds.ifrs + ifrsDelta));
            ds.quality = Math.max(0, Math.min(100, ds.quality + qualityDelta));
            ds.transparency = Math.max(0, Math.min(100, ds.transparency + transparencyDelta));
            ds.risk = Math.max(0, Math.min(100, ds.risk + riskDelta));

            ds.ifrsHistory.push(Math.round(ds.ifrs));
            ds.qualityHistory.push(Math.round(ds.quality));
            ds.riskHistory.push(Math.round(ds.risk));

            // v1.1.0: persist composite for instructor gradebook (results_utils.php Ruta 1).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            if (round === 4) {
                summaryKey = (d.defense === `substance` && d.pattern === `demonstrate`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                ifrs: Math.round(ds.ifrs),
                ifrsDelta: Math.round(ifrsDelta),
                quality: Math.round(ds.quality),
                qualityDelta: Math.round(qualityDelta),
                transparency: Math.round(ds.transparency),
                transparencyDelta: Math.round(transparencyDelta),
                risk: Math.round(ds.risk),
                riskDelta: Math.round(riskDelta),
                ebit: ds.ebit,
                covenant: this._covenant(ds.ebit),
                breachConcealed: ds.breachConcealed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _covenant(ebit) {
            return Math.round((this.NET_DEBT / ebit) * 100) / 100;
        }

        _fmtMoney(valueM) {
            // Locale-aware EUR. EN: €46.8M (symbol before). ES: 46,8 M€ (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const oneDp = Math.round(valueM * 10) / 10;
            if (lang === `es`) {
                return oneDp.toFixed(1).replace(`.`, `,`) + ` M€`;
            }
            return `€` + oneDp.toFixed(1) + `M`;
        }

