            const self = this;
            uiManager.bind(`ebitDisplay`, `domainState.ebit`, (v) => self._fmtMoney(Number(v)));
            uiManager.bind(`covenantDisplay`, `domainState.ebit`, (v) => {
                const cov = self._covenant(Number(v));
                const bar = document.querySelector(`.fairview-ledger-bar`);
                if (bar) bar.classList.toggle(`fairview-covenant-breach`, cov > self.COVENANT_MAX + 0.001);
                return cov.toFixed(2) + `x`;
