        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const ifrs = Math.round(ds.ifrs);
            const quality = Math.round(ds.quality);
            const transparency = Math.round(ds.transparency);
            const risk = Math.round(ds.risk);
            return Math.round(ifrs * 0.30 + quality * 0.30 + transparency * 0.20 + (100 - risk) * 0.20);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const ifrs = Math.round(ds.ifrs);
            const quality = Math.round(ds.quality);
            const transparency = Math.round(ds.transparency);
            const risk = Math.round(ds.risk);
            const cov = this._covenant(ds.ebit);

            // Composite: compliance, quality and transparency reward; audit risk penalises.
            const composite = this._composite(ds);

            const trueAndFair = ifrs >= 60 && quality >= 60 && transparency >= 55 && risk <= 40;
            const concealed = ds.breachConcealed;
            const incentiveLed = ds.incentiveLed;

            let performanceKey = `grade_earnings`;
            if (trueAndFair && composite >= this.TARGET_COMPOSITE) performanceKey = `grade_truefair`;
            else if (trueAndFair) performanceKey = `grade_defensible`;
            else if (concealed) performanceKey = `grade_concealed`;
            else if (incentiveLed) performanceKey = `grade_incentive`;
            else if (composite >= 50) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);
            const met = trueAndFair && composite >= this.TARGET_COMPOSITE;

            const insights = [];
            if (trueAndFair && composite >= this.TARGET_COMPOSITE) insights.push(window.mySimulation.t(`insight_truefair`));
            else if (trueAndFair) insights.push(window.mySimulation.t(`insight_defensible`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (concealed) insights.push(window.mySimulation.t(`insight_concealed`));
            if (incentiveLed) insights.push(window.mySimulation.t(`insight_incentive`));
            if (risk >= 60) insights.push(window.mySimulation.t(`insight_qualified`));
            if (cov > this.COVENANT_MAX + 0.001 && transparency >= 55) insights.push(window.mySimulation.t(`insight_breachok`));
            if (trueAndFair && risk <= this.RISK_FLOOR) insights.push(window.mySimulation.t(`insight_lowrisk`));

            return {
                ifrs: ifrs,
                quality: quality,
                transparency: transparency,
                risk: risk,
                covenant: cov,
                composite: composite,
                trueAndFair: trueAndFair,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                concealed: concealed,
                incentiveLed: incentiveLed,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="fairview-cm-badge ` + (s.met ? `fairview-cm-met` : `fairview-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.concealed) badges.push(`<span class="fairview-cm-badge fairview-cm-fail">` + t(`cm_fail_concealed`) + `</span>`);
            if (s.incentiveLed) badges.push(`<span class="fairview-cm-badge fairview-cm-fail">` + t(`cm_fail_incentive`) + `</span>`);
            if (s.risk != null && s.risk > 40) badges.push(`<span class="fairview-cm-badge fairview-cm-fail">` + t(`cm_fail_risk`) + `</span>`);
            const kpi = (label, val) => `<div class="fairview-cm-metric"><div class="fairview-cm-metric-val">` + val + `</div><div class="fairview-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_ifrs`), (s.ifrs != null ? Math.round(s.ifrs) : 0))
                + kpi(t(`cm_quality`), (s.quality != null ? Math.round(s.quality) : 0))
                + kpi(t(`cm_transparency`), (s.transparency != null ? Math.round(s.transparency) : 0))
                + kpi(t(`cm_risk`), (s.risk != null ? Math.round(s.risk) : 0))
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="fairview-cm">`
                + `<div class="fairview-cm-head"><div class="fairview-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="fairview-cm-scorewrap"><span class="fairview-cm-score">` + score + `</span><span class="fairview-cm-score-max">/100</span></div>`
                + `<div class="fairview-cm-grade">` + grade + `</div>`
                + `<div class="fairview-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="fairview-cm-metrics">` + kpis + `</div>`
                + `<div class="fairview-cm-insights"><div class="fairview-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.breachConcealed) return window.mySimulation.t(`hint_concealed`);
            if (ds.incentiveLed) return window.mySimulation.t(`hint_incentive`);
            if (ds.risk >= 70 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_risk`);
            if (ds.quality < 35) return window.mySimulation.t(`hint_quality`);
            if (ds.ifrs >= 60 && ds.quality >= 60 && ds.risk <= 40) return window.mySimulation.t(`hint_strong`);
            return null;
